    // Part 1 — sport zaliga a'zo bo'lish (forma)
    private static ListeningPart Listening2Part1() => new(1,
        "You will hear a man phoning a fitness centre because he wants to become a member.",
        [
            F("Receptionist", "Good afternoon, Parkside Fitness Centre. How can I help you?"),
            M("Daniel", "Hi. I came in yesterday to have a look round, and I'd like to join. Is it possible to do that over the phone?"),
            F("Receptionist", "Yes, of course. I can set everything up now, and you just sign the form the first time you come in. Can I take your name?"),
            M("Daniel", "It's Daniel Ashworth."),
            F("Receptionist", "Is that A, S, H...?"),
            M("Daniel", "Yes. A, S, H, W, O, R, T, H."),
            F("Receptionist", "Thank you. And could I ask what you do for a living? I'm not being nosy. Some local employers have an arrangement with us, so their staff pay less."),
            M("Daniel", "I'm a nurse. I work on the children's ward at the General Hospital."),
            F("Receptionist", "Ah. I'm afraid the hospital isn't part of our scheme at the moment, but it's useful to know. And how did you hear about us? Was it the leaflet we sent to local homes last month?"),
            M("Daniel", "I did get a leaflet, but to be honest I didn't really read it. It was a colleague who told me about you. She's been coming here for about a year, and she says the classes are excellent."),
            F("Receptionist", "That's lovely to hear. Now, have you thought about which type of membership you'd like? Full membership lets you come in at any time, seven days a week."),
            M("Daniel", "I looked at that, but I work shifts, often in the evenings and at weekends. So I'd mostly be coming in during the day, on weekdays."),
            F("Receptionist", "In that case, the off-peak membership would suit you better. It covers any time before four o'clock from Monday to Friday."),
            M("Daniel", "That sounds ideal. How much is the off-peak membership?"),
            F("Receptionist", "The normal price is 34 pounds a month, but we have a special offer for new members at the moment, so you'd pay 29 pounds a month. That's if you sign up for twelve months. With a six-month contract, the offer price is 33 pounds."),
            M("Daniel", "Well, I'm planning to stay in the area, so I'll go for twelve months."),
            F("Receptionist", "Great. I'll put that down."),
            M("Daniel", "And what does that include? When I looked round, I saw a sauna. Is that included?"),
            F("Receptionist", "The sauna costs a little extra, I'm afraid. It's 3 pounds a visit. But the membership does include all the fitness classes and the swimming pool, so you can swim as often as you like."),
            M("Daniel", "Excellent. I'm not much of a runner, so I'll probably use the swimming pool quite a lot."),
            F("Receptionist", "Before you use any of the gym equipment, all new members have to do an induction with one of our trainers. It takes about an hour. They show you how to use the machines safely and help you plan a programme."),
            M("Daniel", "OK. When could I do that?"),
            F("Receptionist", "Let me see. Wednesday is fully booked, I'm afraid, but we have a space on Thursday morning at ten."),
            M("Daniel", "Thursday's fine. It's my day off."),
            F("Receptionist", "Perfect. For the induction, just wear comfortable clothes and trainers. You don't need to bring a towel, because we provide those, and there's a water fountain in the gym. But please bring a padlock for your locker. We used to lend them out, but too many went missing."),
            M("Daniel", "A padlock. I'll remember. Oh, and one more thing. Is there somewhere to park? The car park at the front looked very full yesterday."),
            F("Receptionist", "That car park belongs to the supermarket, and there's a two-hour limit, so it's best to avoid it. Our members can park free of charge in the car park behind the cinema. It's only a two-minute walk from here."),
            M("Daniel", "Behind the cinema. Great. Thanks very much for your help."),
            F("Receptionist", "You're welcome, Mr Ashworth. See you on Thursday."),
        ],
        [
            new("gap", FormTwoWordsNumber, 2,
            [
                Gap(1, "Name: Daniel ___", ["Ashworth"], "He spells it: \"A, S, H, W, O, R, T, H\"."),
                Gap(2, "Occupation: ___", ["nurse", "a nurse"], "\"I'm a nurse. I work on the children's ward.\""),
                Gap(3, "Heard about the centre from: a ___", ["colleague"], "\"It was a colleague who told me about you\" (he didn't read the leaflet)."),
                Gap(4, "Type of membership: ___", ["off-peak", "off peak"], "\"The off-peak membership would suit you better\" — he works evenings and weekends."),
                Gap(5, "Monthly fee: £ ___", ["29", "£29", "twenty-nine"], "\"You'd pay 29 pounds a month\" (the normal price is 34, and 33 is for six months)."),
                Gap(6, "Length of contract: ___ months", ["12", "twelve"], "\"I'll go for twelve months.\""),
                Gap(7, "Included: all classes and the ___", ["swimming pool", "pool"], "\"The membership does include all the fitness classes and the swimming pool\" (the sauna is extra)."),
                Gap(8, "Induction: ___ at 10 a.m.", ["Thursday"], "\"Wednesday is fully booked ... we have a space on Thursday morning at ten.\""),
                Gap(9, "Bring: a ___ for the locker", ["padlock"], "\"Please bring a padlock for your locker\" (towels are provided)."),
                Gap(10, "Free parking: in the car park behind the ___", ["cinema"], "\"Members can park free of charge in the car park behind the cinema.\""),
            ]),
        ]);

    // Part 2 — muzey audiogidi (mcq + moslashtirish)
    private static ListeningPart Listening2Part2() => new(2,
        "You will hear the introduction to the audio guide of a city museum.",
        [
            M("Audio guide", "Hello, and welcome to the Harbourside Museum. This audio guide will accompany you as you explore our five galleries. Before you set off, here are a few words about how the guide works, and about the museum itself."),
            M("Audio guide", "Throughout the museum you'll see small blue signs beside many of the objects, each with a number on it. To hear the commentary, simply type that number on the keypad and press the green button. There's no need to point the device at the sign, and you don't need to scan anything with your phone."),
            M("Audio guide", "When you've finished your visit, please don't take the guide back to the information desk where you collected it. Just drop it into the box by the exit, and our staff will clean and recharge it for the next visitor."),
            M("Audio guide", "Many visitors assume that this building was once the city's railway station, because of the tall clock tower above the entrance. In fact, the tower was only added in 1890. The building was put up in 1846 as a warehouse for storing wool before it was loaded onto ships in the harbour. It became a museum in 1972."),
            M("Audio guide", "You're welcome to take photographs anywhere in the museum, including the special exhibitions. We only ask you to switch off the flash on your camera or phone, because strong light can damage old fabrics and paintings over time."),
            M("Audio guide", "If you need a break, our café is on the top floor and has wonderful views across the harbour. Please note, though, that it closes at four o'clock, an hour earlier than the museum itself."),
            M("Audio guide", "Now, a little about the galleries. On the ground floor is the River Gallery, which tells the story of the river and the people who worked on it. Most of the objects here are original tools and equipment, and because they're so solid, this is the one gallery where you're allowed to handle them. So do pick up the fishing nets, and try lifting one of the heavy hooks the dockers used."),
            M("Audio guide", "Next door is the Roman Town gallery. The Romans built a small settlement here nearly two thousand years ago, and archaeologists have found coins, pottery and even a child's leather shoe. These objects are far too fragile to touch, of course, but in the small cinema at the end of the gallery you can watch a ten-minute film that shows how the town may have looked."),
            M("Audio guide", "On the first floor is the Victorian Street, one of our most popular galleries. We've rebuilt an entire street from around 1880, with a chemist's shop, a school classroom and a kitchen. Several times a day, staff in costume show visitors how people did their washing, made bread and wrote on slates, so check the times on the board at the entrance to the street."),
            M("Audio guide", "Also on the first floor is the Toy Collection, with more than two thousand toys from the last three centuries. Everything here is kept behind glass, but children can pick up a quiz sheet at the door and look for the answers as they go round. Anyone who finishes it can collect a small prize from the shop."),
            M("Audio guide", "Finally, on the second floor you'll find the Harbour Life gallery. Unlike the others, its displays change every six months. At the moment it's showing photographs of the harbour taken by local people over the last century, and that exhibition runs until the end of March."),
            M("Audio guide", "Guided tours in English and Spanish also leave from the entrance hall at two o'clock every afternoon, if you'd like to join one. Now, please type number one on your keypad to begin."),
        ],
        [
            new("mcq", Abc, null,
            [
                Mcq(11, "To hear information about an object, visitors should", ["enter the number shown on the sign.", "point the device at the sign.", "scan a code with their phone."], "A",
                    "\"Simply type that number on the keypad and press the green button. There's no need to point the device at the sign.\""),
                Mcq(12, "At the end of the visit, visitors should return the audio guide", ["to the information desk.", "to a box by the exit.", "to the museum shop."], "B",
                    "\"Please don't take the guide back to the information desk ... Just drop it into the box by the exit.\""),
                Mcq(13, "The museum building was originally", ["a railway station.", "a clock factory.", "a wool warehouse."], "C",
                    "\"The building was put up in 1846 as a warehouse for storing wool.\""),
                Mcq(14, "What are visitors asked to do when taking photographs?", ["avoid the special exhibitions", "turn off the flash", "buy a photography permit"], "B",
                    "\"We only ask you to switch off the flash on your camera or phone.\""),
                Mcq(15, "What is said about the café?", ["It is on the ground floor.", "It closes before the museum does.", "It overlooks the river."], "B",
                    "\"It closes at four o'clock, an hour earlier than the museum itself.\" It is on the top floor with views of the harbour."),
            ]),
            new("match", "What can visitors find in each gallery?\nChoose FIVE answers from the box and write the correct letter, A–G, next to Questions 16–20.", null,
            [
                Stmt(16, "River Gallery", "B", "\"This is the one gallery where you're allowed to handle them.\""),
                Stmt(17, "Roman Town", "A", "\"In the small cinema at the end of the gallery you can watch a ten-minute film.\" The objects are too fragile to touch."),
                Stmt(18, "Victorian Street", "D", "\"Staff in costume show visitors how people did their washing, made bread and wrote on slates.\""),
                Stmt(19, "Toy Collection", "C", "\"Children can pick up a quiz sheet at the door and look for the answers.\""),
                Stmt(20, "Harbour Life", "E", "\"Its displays change every six months ... that exhibition runs until the end of March.\""),
            ],
            Options: ["a film", "objects that visitors may touch", "an activity for children", "live demonstrations", "a temporary exhibition", "a view of the harbour", "guided tours in two languages"]),
        ]);

    // Part 3 — ikki talaba: talabalar qanday qatnashini o'rganuvchi so'rovnoma
    private static ListeningPart Listening2Part3() => new(3,
        "You will hear two students, Priya and Tom, planning a survey about how students travel to the university.",
        [
            F("Priya", "So, Tom, we really need to finalise the plan for our survey this week. Have you had any more thoughts?"),
            M("Tom", "A few. First, though, the introduction. I thought we could say we chose the topic because we both cycle in and we're interested in making cycling safer."),
            F("Priya", "But that isn't really why, is it? We do both cycle, but the real reason was the announcement that the university's going to close the car park by the science block next year. Nobody seems to know how many people that will affect, and that's what made it interesting."),
            M("Tom", "True. And Dr Hughes didn't suggest it either, it was our own idea. OK. Now, how are we going to collect the data? My first thought was an online questionnaire, because it's so easy to send out."),
            F("Priya", "Yes, but the response rate for online surveys here is terrible. The library survey last year got about five per cent. We also talked about just counting people arriving at the bus stops and bike racks, but that wouldn't tell us why they travel the way they do."),
            M("Tom", "So short face-to-face interviews at the main entrance, then? It'll take longer, but we'll get proper answers."),
            F("Priya", "I think that's the best option. Just five or six questions, so each one only takes a couple of minutes."),
            M("Tom", "And how many people should we aim for? I'd be happy with fifty."),
            F("Priya", "Fifty isn't really enough if we want to compare groups, like first-years and final-years. Dr Hughes said two hundred would be ideal, but I don't think the two of us could manage that in a week."),
            M("Tom", "What about a hundred and fifty, then? That's seventy-five each."),
            F("Priya", "OK, a hundred and fifty it is."),
            M("Tom", "Now, the question about how much people spend on travel. I'm not sure people will know exactly what they spend each week."),
            F("Priya", "No, and some of them won't want to give us an exact figure anyway. Maybe we should just leave cost out altogether."),
            M("Tom", "But cost is probably one of the main reasons people take the bus instead of driving. What if we give them bands, say under ten pounds, ten to twenty pounds, and so on, and they just pick one?"),
            F("Priya", "That's much better. And it's quicker, too."),
            M("Tom", "What do you think the biggest problem will be? I was worried about the weather, but the forecast says it'll be dry next week."),
            F("Priya", "I'm more worried that people will be rushing to lectures and won't want to stop. Especially the ones who arrive at five to nine!"),
            M("Tom", "Good point. We'll just have to be polite and quick. And when we write it up, how shall we show the results? I was going to do a few pie charts."),
            F("Priya", "Everyone does pie charts. I thought a map would be more interesting. We could mark roughly where each person lives and use a different colour for each type of transport. Then you'd see at a glance that, say, everyone near the river cycles."),
            M("Tom", "I like that. It'd look good, too. Right, so what do we need to do before we start?"),
            F("Priya", "Well, first we should try the questions out on a few people to check they're clear. We could use the people in our seminar group on Monday."),
            M("Tom", "Good idea, they won't mind. And we'll need permission to stand at the main entrance, won't we? Do we ask the student union?"),
            F("Priya", "No, I checked. It's the security manager who deals with that, because the entrance is university property. I'll email him today."),
            M("Tom", "Great. And which days? I can't do Monday mornings, and anyway next Monday is a public holiday, so hardly anyone will be in."),
            F("Priya", "Tuesday and Friday, then? That gives us one day early in the week and one at the end, which might show a difference."),
            M("Tom", "Tuesday and Friday, fine. And the last thing: Dr Hughes said we don't have to write a full essay for this one."),
            F("Priya", "That's right. We can present our findings as a poster, and it'll be displayed at the department open day. That's why the map would work so well."),
            M("Tom", "Perfect. Let's get started, then."),
        ],
        [
            new("mcq", Abc, null,
            [
                Mcq(21, "Why did the students choose this topic?", ["They are both keen cyclists.", "The university is going to close a car park.", "Their tutor suggested it."], "B",
                    "\"The real reason was the announcement that the university's going to close the car park by the science block.\""),
                Mcq(22, "How will they collect their data?", ["with an online questionnaire", "by counting people at bus stops and bike racks", "with short interviews at the main entrance"], "C",
                    "\"So short face-to-face interviews at the main entrance, then?\" — \"I think that's the best option.\""),
                Mcq(23, "How many people do they plan to interview?", ["50", "150", "200"], "B",
                    "\"What about a hundred and fifty, then?\" — \"OK, a hundred and fifty it is.\""),
                Mcq(24, "What do they decide about the question on travel costs?", ["to leave it out", "to ask for the exact amount spent each week", "to let people choose a price range"], "C",
                    "\"What if we give them bands ... and they just pick one?\" — \"That's much better.\""),
                Mcq(25, "What problem does Priya expect?", ["bad weather", "people being in a hurry", "people refusing to give personal details"], "B",
                    "\"I'm more worried that people will be rushing to lectures and won't want to stop.\""),
                Mcq(26, "How do they want to present their results?", ["with pie charts", "on a map", "in a table"], "B",
                    "\"I thought a map would be more interesting ... use a different colour for each type of transport.\""),
            ]),
            new("gap", NotesTwoWords, 2,
            [
                Gap(27, "Try out the questions on the people in our ___", ["seminar group"], "\"We could use the people in our seminar group on Monday.\""),
                Gap(28, "Ask for permission from the ___", ["security manager"], "\"It's the security manager who deals with that\" (not the student union)."),
                Gap(29, "Interview days: Tuesday and ___", ["Friday"], "\"Tuesday and Friday, then?\" — Monday is a public holiday."),
                Gap(30, "Present the findings as a ___", ["poster"], "\"We can present our findings as a poster.\""),
            ]),
        ]);

    // Part 4 — ma'ruza: xaritalar tarixi
    private static ListeningPart Listening2Part4() => new(4,
        "You will hear part of a lecture about the history of maps.",
        [
            F("Lecturer", "Good afternoon. Today we're going to look at the history of maps. Maps are so much a part of daily life, especially now that most of us carry one on our phones, that it's easy to forget how recent accurate maps really are. And, as we'll see, maps have always been about more than just finding the way."),
            F("Lecturer", "One of the oldest surviving maps of the world comes from ancient Babylon and dates from around the sixth century BCE. It was drawn on a small clay tablet, and it shows Babylon near the centre, surrounded by a ring of water. It's not a practical map at all. It tells us more about how the Babylonians saw their place in the world than about real geography."),
            F("Lecturer", "A much more scientific approach came from the scholar Ptolemy, who worked in Alexandria in the second century CE. In his book Geography, he listed the positions of thousands of places using a grid of lines, what we now call latitude and longitude. Ptolemy's own maps have not survived, but because he recorded the positions as numbers, later scholars were able to redraw them more than a thousand years afterwards."),
            F("Lecturer", "Now, it's important not to assume that every map places north at the top. In 1154, the geographer al-Idrisi completed a great world map for King Roger the Second of Sicily, combining information from travellers and from earlier books. On his map, south is placed at the top, which was quite normal for many mapmakers in that part of the world."),
            F("Lecturer", "In Christian Europe at around the same period, the best-known maps were large world maps which often put the city of Jerusalem at the centre and had east at the top. These maps were full of pictures of animals, peoples and stories, and they were designed to teach and to inspire, not to help anyone travel from one town to another."),
            F("Lecturer", "For practical purposes, a very different kind of map was far more useful. From the thirteenth century, detailed charts of the Mediterranean began to appear. They showed coastlines and harbours with remarkable accuracy and were covered with straight lines spreading out from compass points. These charts were made for sailors, and they were carried on board ship to help them plan a course from one port to another."),
            F("Lecturer", "Which brings us to one of the most famous maps ever made. In 1569, the Flemish mapmaker Gerardus Mercator published a world map using a new projection, a new way of showing the curved surface of the Earth on a flat sheet. Its great advantage was that a line of constant compass direction appears as a straight line, which made it very valuable for navigation. The disadvantage is that it greatly exaggerates the size of land near the poles. On a Mercator map, Greenland looks roughly as large as Africa, although in reality Africa is about fourteen times larger."),
            F("Lecturer", "Over the next two centuries, the challenge was to measure countries accurately. The key method was triangulation. Surveyors measured one straight line on the ground very carefully, then measured the angles to distant points such as church towers and hilltops, and used geometry to calculate the distances. In France, several generations of the same family spent most of the eighteenth century completing a national survey in this way."),
            F("Lecturer", "In the twentieth century, mapping was transformed by the aeroplane. During and after the First World War, aerial photographs made it possible to map large areas far more quickly than surveyors on foot could ever do. Later, satellites and GPS took this even further."),
            F("Lecturer", "Finally, today's digital maps work in a completely new way. Instead of being a single fixed picture, a digital map is built from separate layers of information, such as roads, buildings, traffic or restaurants, which the user can switch on and off. In the next session, we'll look at how these systems are built and at some of the questions they raise about privacy."),
        ],
        [
            new("gap", NotesOneWord, 1,
            [
                Gap(31, "Babylonian world map: drawn on a small ___ tablet", ["clay"], "\"It was drawn on a small clay tablet.\""),
                Gap(32, "Ptolemy: recorded positions of places using a ___ of lines", ["grid"], "\"Using a grid of lines, what we now call latitude and longitude.\""),
                Gap(33, "al-Idrisi's map (1154): south is at the ___", ["top"], "\"On his map, south is placed at the top.\""),
                Gap(34, "Medieval European world maps: often had ___ at the centre", ["Jerusalem"], "\"Often put the city of Jerusalem at the centre.\""),
                Gap(35, "Mediterranean charts: made for ___ to plan a course", ["sailors"], "\"These charts were made for sailors.\""),
                Gap(36, "Mercator (1569): exaggerates the size of land near the ___", ["poles"], "\"It greatly exaggerates the size of land near the poles.\""),
                Gap(37, "On Mercator's map, Greenland appears about as large as ___", ["Africa"], "\"Greenland looks roughly as large as Africa.\""),
                Gap(38, "Accurate national surveys used a method called ___", ["triangulation"], "\"The key method was triangulation.\""),
                Gap(39, "20th century: ___ photographs allowed large areas to be mapped quickly", ["aerial"], "\"Aerial photographs made it possible to map large areas far more quickly.\""),
                Gap(40, "Digital maps: made up of separate ___ of information", ["layers"], "\"A digital map is built from separate layers of information.\""),
            ]),
        ]);

