    // Part 1 — kichik konferensiya uchun mehmonxona xonalarini band qilish
    private static ListeningPart Listening3Part1() => new(1,
        "You will hear a woman phoning a hotel to book rooms and a meeting room for a small conference.",
        [
            M("James", "Good morning, Lakeview Hotel, events office. James speaking."),
            F("Sophie", "Oh, hello. I'm organising a small conference for our association, and I'd like to book some bedrooms and a meeting room, please."),
            M("James", "Certainly. Could I start with the name of your organisation?"),
            F("Sophie", "Yes, it's the Northern Beekeepers' Association."),
            M("James", "Lovely. And your name?"),
            F("Sophie", "Sophie Maddox. That's M, A, double D, O, X."),
            M("James", "Thank you, Ms Maddox. And what dates are you looking at?"),
            F("Sophie", "We'd originally planned it for September, but a lot of our members are busy with the honey harvest then, so it's now the 18th and 19th of October. That's a Friday and a Saturday."),
            M("James", "Let me check. Yes, we have availability on both nights. How many bedrooms will you need?"),
            F("Sophie", "Two double rooms, and twelve single rooms. Oh, wait, sorry. I had an email this morning. Two more speakers have agreed to come, so that's fourteen single rooms."),
            M("James", "Fourteen singles and two doubles. That's fine. Our standard rate is 95 pounds per room per night, but for groups booking more than ten rooms, we offer a reduced rate of 85 pounds. That includes breakfast, of course."),
            F("Sophie", "That's very helpful. Now, the meeting room. We'll have about forty-five people on the Saturday."),
            M("James", "Then I'm afraid the Library Room won't be big enough. It only seats thirty. I'd suggest the Garden Room. It holds up to sixty, and it opens onto the terrace, which is nice for coffee breaks if the weather's good."),
            F("Sophie", "The Garden Room sounds perfect. What equipment does it have?"),
            M("James", "There's a large screen fixed to the wall, and we can provide whatever else you need."),
            F("Sophie", "We'll need a projector for the talks. And a microphone, please, because some of our speakers are quite softly spoken. We won't need a flip chart."),
            M("James", "A projector and a microphone. No problem. And will you want lunch on the Saturday?"),
            F("Sophie", "Yes, please. What are the options?"),
            M("James", "We can do a sit-down lunch with three courses, served at the tables, or a buffet in the restaurant."),
            F("Sophie", "I think a buffet would be better. People like to move around and keep chatting, and it's usually quicker."),
            M("James", "Of course. Are there any special dietary requirements?"),
            F("Sophie", "Several people are vegetarian."),
            M("James", "That's no problem. Our buffet always has plenty of vegetarian dishes."),
            F("Sophie", "Good. And one of our speakers has a nut allergy, so could the kitchen make sure there's something safe for her?"),
            M("James", "Certainly. I'll make a note for the chef. Now, to confirm the booking we ask for a deposit of twenty per cent by the end of August, and the rest is paid a week after the event."),
            F("Sophie", "The end of August. That's fine. Could you email me the details?"),
            M("James", "Of course. I'll send everything this afternoon."),
        ],
        [
            new("gap", NotesTwoWordsNumber, 2,
            [
                Gap(1, "Organisation: Northern ___ Association", ["Beekeepers", "Beekeepers'"], "\"It's the Northern Beekeepers' Association.\""),
                Gap(2, "Contact name: Sophie ___", ["Maddox"], "She spells it: \"M, A, double D, O, X\"."),
                Gap(3, "Dates: 18th–19th ___", ["October"], "\"We'd originally planned it for September ... so it's now the 18th and 19th of October.\""),
                Gap(4, "Number of single rooms: ___", ["14", "fourteen"], "\"Two more speakers have agreed to come, so that's fourteen single rooms.\""),
                Gap(5, "Group rate: £ ___ per room per night", ["85", "£85"], "\"For groups booking more than ten rooms, we offer a reduced rate of 85 pounds.\""),
                Gap(6, "Meeting room: the ___ Room", ["Garden"], "\"I'd suggest the Garden Room\" — the Library Room only seats thirty."),
