    private static ListeningPart Listening5Part2()
    {
        var map = new MapPlan("Pine Valley Country Park",
            [new("Visitor centre", 2, 4), new("Lake", 2, 2), new("Car park", 4, 4)],
            [
                new("A", 0, 4), new("B", 1, 3), new("C", 0, 1), new("D", 1, 0),
                new("E", 3, 1), new("F", 4, 2), new("G", 3, 3), new("H", 4, 0),
