    // Part 1 — kechki til kursiga yozilish
    private static ListeningPart Listening6Part1() => new(1,
        "You will hear a woman enrolling on an evening language course at an adult education college.",
        [
            M("Receptionist", "Good evening, Westfield Adult Education College. How can I help you?"),
            F("Clare", "Hello. I'd like to enrol on one of your evening language courses, please."),
            M("Receptionist", "Of course. I'll just fill in the form for you. What's your name?"),
            F("Clare", "Clare Farrant. That's F, A, double R, A, N, T."),
            M("Receptionist", "Thank you. And what's your occupation?"),
            F("Clare", "I'm an architect. That's actually why I want to learn a language. My company is working on a project in Brazil next year, and I'll be spending a lot of time there."),
            M("Receptionist", "So you'll be wanting Portuguese?"),
            F("Clare", "Yes. I did think about Italian for a while, because I've always loved Italy, but it makes much more sense to do Portuguese."),
            M("Receptionist", "And have you studied Portuguese before?"),
            F("Clare", "Not at all. I did a bit of Spanish at school, but that was years ago. I'd say I'm a complete beginner."),
            M("Receptionist", "Then the beginner course is right for you. The elementary course is for people who've done about a year already."),
            F("Clare", "Beginner it is. When is it?"),
            M("Receptionist", "Beginner Portuguese is on Tuesday evenings, from half past six to half past eight. There was a Monday class last year, but not enough people signed up for it."),
            F("Clare", "Tuesday suits me fine. Where are the classes held?"),
            M("Receptionist", "Most of our language classes are in the main building, but Portuguese is in the Weston Building. That's W, E, S, T, O, N. It's just across the car park from the main entrance."),
            F("Clare", "OK. And how long is the course?"),
            M("Receptionist", "It runs for ten weeks, starting on the 14th of January."),
            F("Clare", "And the cost?"),
            M("Receptionist", "The full fee is 190 pounds. There's a reduced rate for students and people over sixty."),
            F("Clare", "I'm afraid I'm neither of those."),
            M("Receptionist", "Ah, but if you book before the end of this month, you get the early booking price, which is 165 pounds."),
            F("Clare", "Oh, that's good. I'll book now, then. Is there anything else I need to buy?"),
            M("Receptionist", "The textbook is included in the fee, and you'll get it at the first class. But the teacher asks everyone to buy the workbook that goes with it. It's about fifteen pounds, and you can get it from the college bookshop."),
            F("Clare", "A workbook. Fine. And how can I pay? Can I pay by credit card over the phone?"),
            M("Receptionist", "I'm afraid our card machine isn't working this week. You could come in and pay in cash, or the easiest way is by bank transfer. I'll email you the college's bank details."),
            F("Clare", "Bank transfer is easier for me. Thanks."),
            M("Receptionist", "Lovely. Please pay within five days to keep your place. We look forward to seeing you in January."),
        ],
        [
            new("gap", FormTwoWordsNumber, 2,
            [
                Gap(1, "Name: Clare ___", ["Farrant"], "She spells it: \"F, A, double R, A, N, T\"."),
                Gap(2, "Occupation: ___", ["architect", "an architect"], "\"I'm an architect.\""),
                Gap(3, "Language: ___", ["Portuguese"], "\"It makes much more sense to do Portuguese\" (she thought about Italian)."),
                Gap(4, "Level: ___", ["beginner", "beginners"], "\"The beginner course is right for you\" — elementary is for people with a year of study."),
                Gap(5, "Day: ___ evenings", ["Tuesday"], "\"Beginner Portuguese is on Tuesday evenings.\""),
                Gap(6, "Place: the ___ Building", ["Weston"], "\"Portuguese is in the Weston Building. That's W, E, S, T, O, N.\""),
                Gap(7, "Length of course: ___ weeks", ["10", "ten"], "\"It runs for ten weeks.\""),
                Gap(8, "Fee (early booking): £ ___", ["165", "£165"], "\"If you book before the end of this month ... the early booking price, which is 165 pounds.\""),
                Gap(9, "Must buy: a ___", ["workbook"], "\"The teacher asks everyone to buy the workbook\" (the textbook is included)."),
                Gap(10, "Payment method: ___", ["bank transfer"], "\"The easiest way is by bank transfer\" — \"Bank transfer is easier for me.\""),
            ]),
        ]);

    // Part 2 — yangi savdo markazidagi imkoniyatlar (mcq + moslashtirish)
    private static ListeningPart Listening6Part2() => new(2,
        "You will hear a manager talking about the facilities at a new shopping centre.",
        [
            F("Manager", "Good morning, everyone, and thank you for coming along to this preview of the Millbrook Centre. I'm Sarah Collins, the centre manager, and I'd like to give you a quick introduction before we open our doors to the public next week."),
            F("Manager", "Let me start with a little history. Because of the bus stops right outside, a lot of people think this site used to be the city's bus station. In fact, for almost a century this was the Millbrook biscuit factory, and some of you may remember the smell of baking when you walked past. We've kept the old factory chimney as a feature at the main entrance."),
            F("Manager", "Now, parking. We have spaces for eight hundred cars on two underground levels. The first three hours are free for everyone, and after that there's a small hourly charge, which you can pay at the machines or by card at the exit."),
            F("Manager", "We're also very proud of the building's environmental design. There are solar panels on part of the roof, although they only provide a small share of our electricity. More importantly, the whole roof collects rainwater, which is stored in tanks and then used to flush all the toilets in the building."),
            F("Manager", "We've also launched a free app. At the moment, its main feature is a live display showing how busy each car park level is, so you can find a space quickly. A lot of people have asked whether you'll be able to order food through it, but that's not possible yet. And our loyalty scheme won't start until next year."),
            F("Manager", "For visitors with limited mobility, wheelchairs and mobility scooters are available free of charge from the Mobility Point on the upper car park level. There's no need to book. Just ask a member of staff."),
            F("Manager", "Now, let me tell you about some of our other facilities. For families, there's a large children's play area on the first floor. It's open every day, not just at weekends, but because it's so popular and space is limited, parents must book a session in advance, either online or at the entrance."),
            F("Manager", "We want to encourage people to cycle here, so there's secure bicycle storage by the east entrance. It's covered and has cameras, and it costs nothing to use. You can also rent a locker nearby for your helmet, but that does have a small charge."),
            F("Manager", "On the top floor is our eight-screen cinema. Tickets are the same price every day, but anyone with a valid student card gets twenty per cent off, which I'm sure will be popular with the university just down the road."),
            F("Manager", "Also on the top floor, you'll find the food hall, with twenty restaurants and cafés. Most of our shops close at eight, but the food hall stays open until eleven every night, so you can come for dinner after a film."),
            F("Manager", "One thing that isn't ready yet is our rooftop garden. It will have seating areas and views across the whole city, but the plants need time to establish themselves, so it won't open until the spring."),
            F("Manager", "And finally, the customer service desk. If you visited the centre during our soft opening last month, you'll have seen it just inside the main entrance. It was very crowded there, so it's now on the first floor, next to the lifts. Staff there can help with lost property, gift cards and anything else you need. Right, let's start the tour."),
        ],
        [
            new("mcq", Abc, null,
            [
                Mcq(11, "What was on the site before the shopping centre was built?", ["a bus station", "a factory", "a hospital"], "B",
                    "\"For almost a century this was the Millbrook biscuit factory.\""),
                Mcq(12, "What does the speaker say about parking?", ["It is free for the first three hours.", "It must be paid for through the app.", "Some spaces are for electric cars only."], "A",
                    "\"The first three hours are free for everyone.\""),
                Mcq(13, "What is special about the building's design?", ["It is powered entirely by solar energy.", "Rainwater is used to flush the toilets.", "It was built from recycled materials."], "B",
                    "\"The whole roof collects rainwater, which is ... used to flush all the toilets.\" Solar panels provide only a small share."),
                Mcq(14, "What can visitors currently do with the app?", ["order food", "see how busy the car parks are", "collect loyalty points"], "B",
                    "\"Its main feature is a live display showing how busy each car park level is.\""),
                Mcq(15, "Wheelchairs and mobility scooters", ["must be booked in advance.", "are available for a small fee.", "can be borrowed free of charge."], "C",
                    "\"Available free of charge from the Mobility Point ... There's no need to book.\""),
            ]),
            new("match", "What does the speaker say about each facility?\nChoose FIVE answers from the box and write the correct letter, A–G, next to Questions 16–20.", null,
            [
                Stmt(16, "children's play area", "C", "\"Parents must book a session in advance.\" It is open every day, not only at weekends."),
                Stmt(17, "bicycle storage", "B", "\"It costs nothing to use.\" (Only the lockers have a charge.)"),
                Stmt(18, "cinema", "G", "\"Anyone with a valid student card gets twenty per cent off.\""),
                Stmt(19, "food hall", "D", "\"Most of our shops close at eight, but the food hall stays open until eleven.\""),
                Stmt(20, "customer service desk", "F", "\"It was very crowded there, so it's now on the first floor, next to the lifts.\""),
            ],
            Options: ["It is only open at weekends.", "It is free to use.", "It must be booked in advance.", "It stays open later than the shops.", "It is not open yet.", "It has moved to a new location.", "It offers a discount to students."]),
        ]);

    // Part 3 — guruh loyihasi: universitetda suvni tejash
    private static ListeningPart Listening6Part3() => new(3,
        "You will hear two students, Grace and Sam, talking to their tutor about their group project on saving water at the university.",
        [
            M("Dr Novak", "Hello, Grace, Sam. Come in. So, you've finished the water audit for your project. What did you find?"),
            F("Grace", "Quite a lot, actually. The first thing is where the most water is used. We assumed it would be the halls of residence, because of all the showers and kitchens. But the biggest user by far is the sports centre, with the swimming pool and all the changing rooms."),
            M("Dr Novak", "Interesting. And did you find much being wasted?"),
            M("Sam", "Yes. We did a walk round every building and checked all the taps and toilets. Most were fine, but the old library was the worst. We found eleven dripping taps there, mostly in the basement toilets."),
            F("Grace", "And the sports fields were a surprise. The sprinklers are on an automatic timer, so they come on even during heavy rain. We watched it happen twice."),
            M("Dr Novak", "That's an easy one to fix. And what about the halls?"),
            M("Sam", "We asked students to time their showers for a week. The average shower lasted nine minutes, which is quite a lot longer than the national average."),
            M("Dr Novak", "Good. Now, my main concern is the data itself. You measured everything carefully, and you covered all the main buildings, which is good. But everything was collected in just one week in October. Water use changes a lot over the year. In summer, for example, the sprinklers run much more."),
            F("Grace", "That's true. We can't really go back and collect more now, but we'll explain it in the report."),
            M("Dr Novak", "Fine. Now, your recommendations. I see you've decided against shower timers. Why was that? Was it the cost?"),
            M("Sam", "They're actually quite cheap. The problem is that a study at another university found they made no difference. Students just ignored them. So there didn't seem much point."),
            M("Dr Novak", "Fair enough. What do you want to recommend first, then? I see you've got rainwater tanks and new toilets on your list."),
            F("Grace", "We thought rainwater tanks on the sports centre roof would save the most water."),
            M("Dr Novak", "They might, in the long run, but they're expensive and they'd take time to install. I'd put repairing all the leaks at the top of the list. It costs very little, and the savings start immediately."),
            F("Grace", "OK, that makes sense. We'll put that first."),
            M("Dr Novak", "And you mentioned an awareness campaign?"),
            M("Sam", "Yes. We thought about putting stickers above all the sinks, but people stop noticing those after a few days. So instead we're going to organise a competition between the halls of residence to see which one can reduce its water use the most. The winning hall gets a prize."),
            M("Dr Novak", "I like that. Students love a competition. How will you know if it's worked?"),
            F("Grace", "We thought about asking students whether they'd changed their habits, but people don't always tell the truth in surveys. Each hall has its own water meter, so we'll compare the readings before and after the competition."),
            M("Dr Novak", "Much more reliable. Finally, the draft report. The literature review is thorough, and the conclusion is clear. The weakest part is the section on costs. You give figures for installing the tanks and new toilets, but you don't say where those figures come from. You'll need to include your sources."),
            F("Grace", "Right, we'll add those. Thanks, Dr Novak."),
        ],
        [
            new("gap", NotesTwoWordsNumber, 2,
            [
                Gap(21, "Biggest user of water: the ___", ["sports centre"], "\"The biggest user by far is the sports centre\" (not the halls of residence)."),
                Gap(22, "Most dripping taps were found in the ___", ["old library"], "\"The old library was the worst. We found eleven dripping taps there.\""),
                Gap(23, "Sprinklers on the sports fields come on even during heavy ___", ["rain"], "\"They come on even during heavy rain.\""),
                Gap(24, "Average shower in the halls: ___ minutes", ["9", "nine"], "\"The average shower lasted nine minutes.\""),
            ]),
            new("mcq", Abc, null,
            [
                Mcq(25, "What is the tutor's main concern about the students' data?", ["It was only collected over one week.", "It only covered some of the buildings.", "Some of it was estimated."], "A",
                    "\"Everything was collected in just one week in October. Water use changes a lot over the year.\""),
                Mcq(26, "Why did the students decide not to recommend shower timers?", ["They are too expensive.", "There is evidence that they do not work.", "The university has already rejected them."], "B",
                    "\"A study at another university found they made no difference.\" They are \"actually quite cheap\"."),
                Mcq(27, "What does the tutor think should be done first?", ["installing rainwater tanks", "replacing old toilets", "repairing leaks"], "C",
                    "\"I'd put repairing all the leaks at the top of the list.\""),
                Mcq(28, "For their awareness campaign, the students will", ["put stickers above sinks.", "run a competition between halls.", "send emails to all students."], "B",
                    "\"We're going to organise a competition between the halls of residence.\""),
                Mcq(29, "How will they measure the success of the campaign?", ["by surveying students", "by comparing water meter readings", "by counting the number of participants"], "B",
                    "\"We'll compare the readings before and after the competition.\""),
                Mcq(30, "According to the tutor, the weakest part of the draft report is", ["the literature review.", "the cost information.", "the conclusion."], "B",
                    "\"The weakest part is the section on costs ... You'll need to include your sources.\""),
            ]),
        ]);

    // Part 4 — ma'ruza: pochta xizmati tarixi
    private static ListeningPart Listening6Part4() => new(4,
        "You will hear part of a lecture about the history of the postal service.",
        [
            M("Lecturer", "Good morning. Today we're going to look at the history of the postal service. It's something most of us take for granted, but the ability to send a message across a country, or across the world, cheaply and reliably, is actually quite a recent achievement."),
            M("Lecturer", "Organised systems for carrying messages go back thousands of years. The ancient Persian Empire, for example, had a network of royal roads with stations about a day's ride apart. At each station, fresh horses and riders were waiting, so a message could be passed along the chain and travel very long distances in a matter of days."),
            M("Lecturer", "The Romans built a similar system. However, like the Persian one, it was not for ordinary people. It existed mainly for government business: carrying official letters, orders and news between Rome and the provinces. Private individuals had to send letters with friends, travellers or their own servants."),
            M("Lecturer", "In the centuries that followed, various groups ran their own courier services, including merchants and universities. Gradually, however, many European countries created national postal services. In Britain, the royal post was opened to the public in 1635."),
            M("Lecturer", "But the system was far from perfect. Until 1840, letters in Britain were usually paid for by the receiver, not the sender. And the cost depended on two things: the distance the letter travelled and the number of sheets of paper it contained. Sending a long letter across the country could cost more than a working person earned in a day. Not surprisingly, many people refused to accept letters, or found clever ways to avoid paying."),
            M("Lecturer", "The man who changed all this was Rowland Hill, a teacher and reformer. In 1837, he published a proposal for a single, low price for any letter within the country, whatever the distance. Crucially, the charge would be paid in advance by the sender. To show that a letter had been paid for, Hill suggested a small printed label that could be stuck on the envelope, in other words, a stamp."),
            M("Lecturer", "The first stamp, known as the Penny Black, went on sale in May 1840. It showed the head of the young Queen Victoria. The reform was a huge success. The number of letters sent in Britain roughly doubled in the first year, and other countries soon copied the idea."),
            M("Lecturer", "Of course, if people were going to send more letters, they needed convenient places to post them. In the 1850s, the first roadside post boxes appeared in Britain. The idea is often credited to the novelist Anthony Trollope, who worked for the Post Office for many years and had seen similar boxes in France."),
            M("Lecturer", "Sending letters abroad remained complicated, because every country had its own rules and prices. In 1874, representatives of many countries met in the Swiss city of Bern and set up what became the Universal Postal Union. Member countries agreed to treat international mail on similar terms, which made sending a letter abroad far simpler."),
            M("Lecturer", "In the twentieth century, the volume of mail grew so large that sorting by hand became a real problem. This led to the introduction of postcodes in many countries, so that letters could be sorted by machine."),
            M("Lecturer", "And today? The number of letters has fallen sharply, as people communicate by email and messaging apps. But postal services have found a new role. Because of the growth of online shopping, they now deliver far more parcels than ever before. In our next session, we'll look at how postal companies have adapted to these changes."),
        ],
        [
            new("gap", NotesOneWord, 1,
            [
                Gap(31, "Persian Empire: fresh ___ and riders waited at stations along royal roads", ["horses"], "\"At each station, fresh horses and riders were waiting.\""),
                Gap(32, "Roman system: mainly used for ___ business", ["government"], "\"It existed mainly for government business.\""),
                Gap(33, "Before 1840 in Britain: letters usually paid for by the ___", ["receiver", "recipient"], "\"Letters in Britain were usually paid for by the receiver, not the sender.\""),
                Gap(34, "Cost depended on distance and the number of ___", ["sheets"], "\"The number of sheets of paper it contained.\""),
                Gap(35, "Rowland Hill: one low price, paid in ___ by the sender", ["advance"], "\"The charge would be paid in advance by the sender.\""),
                Gap(36, "Penny Black (1840): showed the head of the ___", ["Queen"], "\"It showed the head of the young Queen Victoria.\""),
                Gap(37, "Roadside post boxes: idea often credited to a ___", ["novelist"], "\"The idea is often credited to the novelist Anthony Trollope.\""),
                Gap(38, "Universal Postal Union: set up in 1874 in ___", ["Bern", "Berne"], "\"Representatives of many countries met in the Swiss city of Bern.\""),
                Gap(39, "Postcodes: introduced so letters could be sorted by ___", ["machine", "machines"], "\"So that letters could be sorted by machine.\""),
                Gap(40, "Today: postal services deliver many more ___", ["parcels"], "\"They now deliver far more parcels than ever before.\""),
            ]),
        ]);
}
